mod obj_parser;
mod stl_parser;
mod mesh;
mod renderer;
mod colors;

use std::fs;
use std::path::Path;
use clap::{App, Arg, SubCommand};
use nalgebra as na;

fn main() {
    let app = App::new("Sloth")
        .version("0.1")
        .author("Mitchell Hynes. <mshynes@mun.ca>")
        .about("A toy for rendering 3D objects in the command line")
        .arg(
            Arg::with_name("input filename(s)")
                .multiple(true)
                .required(true)
                .index(1)
                .help("Sets the input file to render"),
        )
        .arg(
            Arg::with_name("b")
                .short("b")
                .help("Flags the rasterizer to render without color"),
        )
        .arg(
            Arg::with_name("x")
                .short("x")
                .long("yaw")
                .takes_value(true)
                .help("Sets the object's static X rotation (in radians)"),
        )
        .arg(
            Arg::with_name("y")
                .short("y")
                .long("pitch")
                .takes_value(true)
                .help("Sets the object's static Y rotation (in radians)"),
        )
        .arg(
            Arg::with_name("z")
                .short("z")
                .long("roll")
                .takes_value(true)
                .help("Sets the object's static Z rotation (in radians)"),
        )
        .subcommand(
            SubCommand::with_name("image")
                .about("Generates a colorless terminal output as lines of text")
                .author("Mitchell Hynes <mitchell.hynes@ecumene.xyz>")
                .arg(
                    Arg::with_name("b")
                        .short("b")
                        .help("Flags the rasterizer to render without color"),
                )
                .arg(
                    Arg::with_name("w")
                        .short("w")
                        .long("width")
                        .takes_value(true)
                        .required(true)
                        .help("Sets the width of the image to generate"),
                )
                .arg(
                    Arg::with_name("h")
                        .short("h")
                        .long("height")
                        .takes_value(true)
                        .help("Sets the height of the image to generate"),
                )
                .arg(
                    Arg::with_name("x")
                        .short("x")
                        .long("yaw")
                        .takes_value(true)
                        .help("Sets the object's static X rotation (in radians)"),
                )
                .arg(
                    Arg::with_name("y")
                        .short("y")
                        .long("pitch")
                        .takes_value(true)
                        .help("Sets the object's static Y rotation (in radians)"),
                )
                .arg(
                    Arg::with_name("z")
                        .short("z")
                        .long("roll")
                        .takes_value(true)
                        .help("Sets the object's static Z rotation (in radians)"),
                )
                .arg(
                    Arg::with_name("j")
                        .short("j")
                        .long("webify")
                        .takes_value(true)
                        .help("Generates a portable JS based render of your object for the web"),
                ),
        );

    let matches = app.get_matches();

    let black_and_white = matches.is_present("b");
    let x_rot: f32 = matches
        .value_of("x")
        .unwrap_or("0")
        .parse()
        .unwrap_or(0.0);
    let y_rot: f32 = matches
        .value_of("y")
        .unwrap_or("0")
        .parse()
        .unwrap_or(0.0);
    let z_rot: f32 = matches
        .value_of("z")
        .unwrap_or("0")
        .parse()
        .unwrap_or(0.0);

    let input_files: Vec<&str> = matches
        .values_of("input filename(s)")
        .unwrap_or_default()
        .collect();

    if let Some(image_matches) = matches.subcommand_matches("image") {
        let width: u32 = image_matches
            .value_of("w")
            .unwrap_or("800")
            .parse()
            .unwrap_or(800);
        let height: u32 = image_matches
            .value_of("h")
            .unwrap_or("600")
            .parse()
            .unwrap_or(600);
        let bw = image_matches.is_present("b") || black_and_white;

        let x_rot_img: f32 = image_matches
            .value_of("x")
            .unwrap_or(&x_rot.to_string())
            .parse()
            .unwrap_or(x_rot);
        let y_rot_img: f32 = image_matches
            .value_of("y")
            .unwrap_or(&y_rot.to_string())
            .parse()
            .unwrap_or(y_rot);
        let z_rot_img: f32 = image_matches
            .value_of("z")
            .unwrap_or(&z_rot.to_string())
            .parse()
            .unwrap_or(z_rot);

        let mut combined_mesh = mesh::Mesh::new();
        for file in &input_files {
            let loaded_mesh = load_mesh(file);
            combined_mesh.merge(loaded_mesh);
        }

        renderer::render_image(&combined_mesh, width, height, x_rot_img, y_rot_img, z_rot_img, bw);
    } else {
        eprintln!("Error: Interactive terminal rendering not supported in this environment");
    }
}

fn load_mesh(filename: &str) -> mesh::Mesh {
    let path = Path::new(filename);
    if filename.ends_with(".obj") {
        obj_parser::parse_obj(filename).unwrap_or_else(|e| {
            eprintln!("Error loading OBJ file: {}", e);
            std::process::exit(1);
        })
    } else if filename.ends_with(".stl") {
        stl_parser::parse_stl(filename).unwrap_or_else(|e| {
            eprintln!("Error loading STL file: {}", e);
            std::process::exit(1);
        })
    } else {
        eprintln!("Unsupported file format");
        std::process::exit(1);
    }
}
EOF

