cat > src/mesh.rs << 'EOF'
use nalgebra as na;

#[derive(Clone, Debug)]
pub struct Vertex {
    pub position: na::Vector3<f32>,
    pub normal: na::Vector3<f32>,
    pub color: (u8, u8, u8),
}

#[derive(Clone, Debug)]
pub struct Face {
    pub vertices: [usize; 3],
}

pub struct Mesh {
    pub vertices: Vec<Vertex>,
    pub faces: Vec<Face>,
}

impl Mesh {
    pub fn new() -> Self {
        Mesh {
            vertices: Vec::new(),
            faces: Vec::new(),
        }
    }

    pub fn merge(&mut self, other: Mesh) {
        let offset = self.vertices.len();
        self.vertices.extend(other.vertices);
        for mut face in other.faces {
            face.vertices[0] += offset;
            face.vertices[1] += offset;
            face.vertices[2] += offset;
            self.faces.push(face);
        }
    }

    pub fn apply_rotation(&mut self, x_rot: f32, y_rot: f32, z_rot: f32) {
        let rx = na::Matrix3::new_rotation(na::Vector3::x_axis() * x_rot);
        let ry = na::Matrix3::new_rotation(na::Vector3::y_axis() * y_rot);
        let rz = na::Matrix3::new_rotation(na::Vector3::z_axis() * z_rot);

        let rotation = rz * ry * rx;

        for vertex in &mut self.vertices {
            vertex.position = rotation * vertex.position;
            vertex.normal = rotation * vertex.normal;
        }
    }

    pub fn get_bounds(&self) -> Option<(na::Vector3<f32>, na::Vector3<f32>)> {
        if self.vertices.is_empty() {
            return None;
        }

        let mut min = self.vertices[0].position;
        let mut max = self.vertices[0].position;

