        match parts[0] {
            "v" => {
                if parts.len() >= 4 {
                    let x = parts[1].parse::<f32>().unwrap_or(0.0);
                    let y = parts[2].parse::<f32>().unwrap_or(0.0);
                    let z = parts[3].parse::<f32>().unwrap_or(0.0);
                    vertices.push(na::Vector3::new(x, y, z));
                }
            }
            "vn" => {
                if parts.len() >= 4 {
                    let x = parts[1].parse::<f32>().unwrap_or(0.0);
                    let y = parts[2].parse::<f32>().unwrap_or(0.0);
                    let z = parts[3].parse::<f32>().unwrap_or(0.0);
                    normals.push(na::Vector3::new(x, y, z).normalize());
                }
            }
            "f" => {
                if parts.len() >= 4 {
                    let mut face_vertices = Vec::new();
                    for i in 1..parts.len() {
                        let indices: Vec<&str> = parts[i].split('/').collect();
                        if let Ok(v_idx) = indices[0].parse::<usize>() {
                            face_vertices.push(v_idx - 1);
                        }
                    }

                    // Triangulate polygons
                    for i in 1..face_vertices.len() - 1 {
                        faces.push(Face {
                            vertices: [face_vertices[0], face_vertices[i], face_vertices[i + 1]],
                        });
                    }
                }
            }
            "usemtl" => {
                if parts.len() >= 2 {
                    current_material = materials
                        .get(parts[1])
                        .copied()
                        .unwrap_or((128, 128, 128));
                }
            }
            "mtllib" => {
                if let Some(dir) = &mtl_path {
                    if parts.len() >= 2 {
                        let mtl_file = dir.join(parts[1]);
                        if let Ok(mtl_data) = parse_mtl(mtl_file.to_str().unwrap_or("")) {
                            materials.extend(mtl_data);
                        }
                    }
                }
            }
            _ => {}
        }
    }

    if vertices.is_empty() {
        return Err("No vertices found in OBJ file".to_string());
    }

    let mut mesh_vertices = Vec::new();
    for (i, pos) in vertices.iter().enumerate() {
        let normal = if i < normals.len() {
            normals[i]
        } else {
            na::Vector3::new(0.0, 0.0, 1.0)
        };

        mesh_vertices.push(Vertex {
            position: *pos,
            normal,
            color: current_material,
        });
    }

    Ok(Mesh {
        vertices: mesh_vertices,
        faces,
    })
}

fn parse_mtl(filename: &str) -> Result<HashMap<String, (u8, u8, u8)>, String> {
    let file = File::open(filename).map_err(|e| format!("Cannot open MTL file: {}", e))?;
    let reader = BufReader::new(file);

    let mut materials = HashMap::new();
    let mut current_name = String::new();
    let mut current_color = (128u8, 128u8, 128u8);

    for line in reader.lines() {
        let line = line.map_err(|e| format!("Read error: {}", e))?;
        let line = line.trim();

        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }

        match parts[0] {
            "newmtl" => {
                if !current_name.is_empty() {
                    materials.insert(current_name, current_color);
                }
                current_name = parts.get(1).map(|s| s.to_string()).unwrap_or_default();
                current_color = (128, 128, 128);
            }
            "Kd" => {
                if parts.len() >= 4 {
                    let r = (parts[1].parse::<f32>().unwrap_or(0.0) * 255.0) as u8;
                    let g = (parts[2].parse::<f32>().unwrap_or(0.0) * 255.0) as u8;
                    let b = (parts[3].parse::<f32>().unwrap_or(0.0) * 255.0) as u8;
                    current_color = (r, g, b);
                }
            }
            _ => {}
        }
    }

    if !current_name.is_empty() {
        materials.insert(current_name, current_color);
    }

    Ok(materials)
}
