        let normal = na::Vector3::new(
            f32::from_le_bytes([
                normal_bytes[0],
                normal_bytes[1],
                normal_bytes[2],
                normal_bytes[3],
            ]),
            f32::from_le_bytes([
                normal_bytes[4],
                normal_bytes[5],
                normal_bytes[6],
                normal_bytes[7],
            ]),
            f32::from_le_bytes([
                normal_bytes[8],
                normal_bytes[9],
                normal_bytes[10],
                normal_bytes[11],
            ]),
        )
        .normalize();

        let v1 = na::Vector3::new(
            f32::from_le_bytes([v1_bytes[0], v1_bytes[1], v1_bytes[2], v1_bytes[3]]),
            f32::from_le_bytes([v1_bytes[4], v1_bytes[5], v1_bytes[6], v1_bytes[7]]),
            f32::from_le_bytes([v1_bytes[8], v1_bytes[9], v1_bytes[10], v1_bytes[11]]),
        );

        let v2 = na::Vector3::new(
            f32::from_le_bytes([v2_bytes[0], v2_bytes[1], v2_bytes[2], v2_bytes[3]]),
            f32::from_le_bytes([v2_bytes[4], v2_bytes[5], v2_bytes[6], v2_bytes[7]]),
            f32::from_le_bytes([v2_bytes[8], v2_bytes[9], v2_bytes[10], v2_bytes[11]]),
        );

        let v3 = na::Vector3::new(
            f32::from_le_bytes([v3_bytes[0], v3_bytes[1], v3_bytes[2], v3_bytes[3]]),
            f32::from_le_bytes([v3_bytes[4], v3_bytes[5], v3_bytes[6], v3_bytes[7]]),
            f32::from_le_bytes([v3_bytes[8], v3_bytes[9], v3_bytes[10], v3_bytes[11]]),
        );

        let idx1 = vertices.len();
        vertices.push(Vertex {
            position: v1,
            normal,
            color: (128, 128, 128),
        });

        let idx2 = vertices.len();
        vertices.push(Vertex {
            position: v2,
            normal,
            color: (128, 128, 128),
        });

        let idx3 = vertices.len();
        vertices.push(Vertex {
            position: v3,
            normal,
            color: (128, 128, 128),
        });

        faces.push(Face {
            vertices: [idx1, idx2, idx3],
        });
    }

    Ok(Mesh { vertices, faces })
}

fn parse_stl_ascii(file: &mut File) -> Result<Mesh, String> {
    let mut content = String::new();
    file.read_to_string(&mut content)
        .map_err(|e| format!("Failed to read file: {}", e))?;

    let mut vertices = Vec::new();
    let mut faces = Vec::new();
    let mut current_normal = na::Vector3::new(0.0, 0.0, 1.0);

    for line in content.lines() {
        let line = line.trim();

        if line.starts_with("facet normal") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 5 {
                current_normal = na::Vector3::new(
                    parts[2].parse().unwrap_or(0.0),
                    parts[3].parse().unwrap_or(0.0),
                    parts[4].parse().unwrap_or(0.0),
                )
                .normalize();
            }
        } else if line.starts_with("vertex") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 4 {
                let x = parts[1].parse().unwrap_or(0.0);
                let y = parts[2].parse().unwrap_or(0.0);
                let z = parts[3].parse().unwrap_or(0.0);

                vertices.push(Vertex {
                    position: na::Vector3::new(x, y, z),
                    normal: current_normal,
                    color: (128, 128, 128),
                });

                if vertices.len() % 3 == 0 {
                    let idx = vertices.len();
                    faces.push(Face {
                        vertices: [idx - 3, idx - 2, idx - 1],
                    });
                }
            }
        }
    }

    Ok(Mesh { vertices, faces })
}
