use crate::mesh::Mesh;
use crate::colors;
use nalgebra as na;
use std::f32;

const BACKGROUND_COLOR: (u8, u8, u8) = (25, 25, 25);

pub fn render_image(
    mesh: &Mesh,
    width: u32,
    height: u32,
    x_rot: f32,
    y_rot: f32,
    z_rot: f32,
    black_and_white: bool,
) {
    let mut mesh = mesh.clone();
    mesh.apply_rotation(x_rot, y_rot, z_rot);

    // Center and scale the mesh
    if let Some((min, max)) = mesh.get_bounds() {
        let center = (min + max) / 2.0;
        let size = max - min;
        let max_dim = size.x.max(size.y).max(size.z);

        // Scale to fit screen
        let scale = if max_dim > 0.0 {
            (width.min(height) as f32 * 0.8) / max_dim
        } else {
            1.0
        };

        for vertex in &mut mesh.vertices {
            vertex.position -= center;
            vertex.position *= scale;
        }
    }

    // Create framebuffer
    let mut framebuffer = vec![FramebufferPixel::default(); (width * height) as usize];
    let mut depthbuffer = vec![f32::MAX; (width * height) as usize];

    // Rasterize all faces
    for face in &mesh.faces {
        rasterize_triangle(
            &mesh,
            face.vertices,
            width,
            height,
            &mut framebuffer,
            &mut depthbuffer,
            black_and_white,
        );
    }

    // Output framebuffer
    output_framebuffer(&framebuffer, width, height);
}

#[derive(Clone, Copy, Default)]
struct FramebufferPixel {
    color: (u8, u8, u8),
}

fn rasterize_triangle(
    mesh: &Mesh,
    vertex_indices: [usize; 3],
    width: u32,
    height: u32,
    framebuffer: &mut [FramebufferPixel],
    depthbuffer: &mut [f32],
    black_and_white: bool,
) {
    let v0 = mesh.vertices[vertex_indices[0]].position;
    let v1 = mesh.vertices[vertex_indices[1]].position;
    let v2 = mesh.vertices[vertex_indices[2]].position;

    let n0 = mesh.vertices[vertex_indices[0]].normal;
    let n1 = mesh.vertices[vertex_indices[1]].normal;
    let n2 = mesh.vertices[vertex_indices[2]].normal;

    let c0 = mesh.vertices[vertex_indices[0]].color;
    let c1 = mesh.vertices[vertex_indices[1]].color;
    let c2 = mesh.vertices[vertex_indices[2]].color;

    // Project to screen space
    let p0 = project_to_screen(v0, width, height);
    let p1 = project_to_screen(v1, width, height);
    let p2 = project_to_screen(v2, width, height);

    // Backface culling
    let edge0 = p1 - p0;
    let edge1 = p2 - p1;
    let cross = edge0.x * edge1.y - edge0.y * edge1.x;
    if cross <= 0.0 {
        return;
    }

    // Get bounding box
    let min_x = (p0.x.min(p1.x).min(p2.x).floor() as i32).max(0).min(width as i32 - 1);
    let max_x = (p0.x.max(p1.x).max(p2.x).ceil() as i32).max(0).min(width as i32 - 1);
    let min_y = (p0.y.min(p1.y).min(p2.y).floor() as i32).max(0).min(height as i32 - 1);
    let max_y = (p0.y.max(p1.y).max(p2.y).ceil() as i32).max(0).min(height as i32 - 1);

    for y in min_y..=max_y {
        for x in min_x..=max_x {
            let px = x as f32 + 0.5;
            let py = y as f32 + 0.5;

            // Barycentric coordinates
            if let Some((u, v, w)) = barycentric(p0, p1, p2, na::Vector2::new(px, py)) {
                if u >= 0.0 && v >= 0.0 && w >= 0.0 {
                    // Interpolate depth
                    let depth = u * v0.z + v * v1.z + w * v2.z;

                    let idx = (y as u32 * width + x as u32) as usize;
                    if depth < depthbuffer[idx] {
                        // Interpolate normal
                        let normal = (u * n0 + v * n1 + w * n2).normalize();

                        // Lighting
                        let light_dir = na::Vector3::new(0.577, 0.577, 0.577).normalize();
                        let intensity = (normal.dot(&light_dir).max(0.2)).min(1.0);

                        // Interpolate color
                        let base_color = (
                            ((u * c0.0 as f32 + v * c1.0 as f32 + w * c2.0 as f32) as u8)),
                            ((u * c0.1 as f32 + v * c1.1 as f32 + w * c2.1 as f32) as u8)),
                            ((u * c0.2 as f32 + v * c1.2 as f32 + w * c2.2 as f32) as u8)),
                        );

                        let color = if black_and_white {
                            let gray = ((intensity * 200.0) as u8).saturating_add(25);
                            (gray, gray, gray)
                        } else {
                            (
                                ((base_color.0 as f32 * intensity) as u8),
                                ((base_color.1 as f32 * intensity) as u8),
                                ((base_color.2 as f32 * intensity) as u8),
                            )
                        };

                        framebuffer[idx].color = color;
                        depthbuffer[idx] = depth;
                    }
                }
            }
        }
    }
}

fn project_to_screen(pos: na::Vector3<f32>, width: u32, height: u32) -> na::Vector2<f32> {
    let w = width as f32;
    let h = height as f32;

    // Simple orthographic projection centered
    let x = (pos.x + w / 2.0);
    let y = (pos.y + h / 2.0);

    na::Vector2::new(x, y)
}

fn barycentric(
    a: na::Vector2<f32>,
    b: na::Vector2<f32>,
    c: na::Vector2<f32>,
    p: na::Vector2<f32>,
) -> Option<(f32, f32, f32)> {
    let v0 = c - a;
    let v1 = b - a;
    let v2 = p - a;

    let dot00 = v0.dot(&v0);
    let dot01 = v0.dot(&v1);
    let dot02 = v0.dot(&v2);
    let dot11 = v1.dot(&v1);
    let dot12 = v1.dot(&v2);

    let denom = dot00 * dot11 - dot01 * dot01;
    if denom.abs() < 1e-10 {
        return None;
    }

    let inv_denom = 1.0 / denom;
    let u = (dot11 * dot02 - dot01 * dot12) * inv_denom;
    let v = (dot00 * dot12 - dot01 * dot02) * inv_denom;
    let w = 1.0 - u - v;

    Some((u, v, w))
}

fn output_framebuffer(framebuffer: &[FramebufferPixel], width: u32, height: u32) {
    let mut output = String::new();

    for y in 0..height {
        for x in 0..width {
            let idx = (y * width + x) as usize;
            let color = framebuffer[idx].color;

            output.push_str(&colors::rgb_to_ansi_bg(color.0, color.1, color.2));
            output.push_str(&colors::rgb_to_ansi_fg(0, 0, 0));
            output.push(' ');
            output.push_str(colors::reset_bg());
            output.push_str(colors::reset_fg());
        }
        output.push('\n');
    }

    print!("{}", output);
}
