use crate::math::Vec3;

#[derive(Clone, Debug)]
pub struct Vertex {
    pub position: Vec3,
    pub normal: Vec3,
    pub color: (u8, u8, u8),
}

#[derive(Clone, Debug)]
pub struct Face {
    pub vertices: [usize; 3],
}

pub struct Mesh {
    pub vertices: Vec<Vertex>,
    pub faces: Vec<Face>,
}

impl Mesh {
    pub fn new() -> Self {
        Mesh {
            vertices: Vec::new(),
            faces: Vec::new(),
        }
    }

    pub fn merge(&mut self, other: Mesh) {
        let offset = self.vertices.len();
        self.vertices.extend(other.vertices);
        for mut face in other.faces {
            face.vertices[0] += offset;
            face.vertices[1] += offset;
            face.vertices[2] += offset;
            self.faces.push(face);
        }
    }

    pub fn apply_rotation(&mut self, x_rot: f32, y_rot: f32, z_rot: f32) {
        use crate::math::Mat3;

        let rx = Mat3::rotate_x(x_rot);
        let ry = Mat3::rotate_y(y_rot);
        let rz = Mat3::rotate_z(z_rot);

        let rotation = rz.mul(&ry).mul(&rx);

        for vertex in &mut self.vertices {
            vertex.position = rotation.mul_vec(&vertex.position);
            vertex.normal = rotation.mul_vec(&vertex.normal);
        }
    }

    pub fn get_bounds(&self) -> Option<(Vec3, Vec3)> {
        if self.vertices.is_empty() {
            return None;
        }

        let mut min = self.vertices[0].position;
        let mut max = self.vertices[0].position;

        for vertex in &self.vertices {
            min.x = min.x.min(vertex.position.x);
            min.y = min.y.min(vertex.position.y);
            min.z = min.z.min(vertex.position.z);

            max.x = max.x.max(vertex.position.x);
            max.y = max.y.max(vertex.position.y);
            max.z = max.z.max(vertex.position.z);
        }

        Some((min, max))
    }
}
