use crate::mesh::{Mesh, Vertex, Face};
use crate::math::Vec3;
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};

pub fn parse_stl(filename: &str) -> Result<Mesh, String> {
    let mut file = File::open(filename).map_err(|e| format!("Cannot open file: {}", e))?;

    // Try binary format first
    if let Ok(mesh) = parse_stl_binary(&mut file) {
        return Ok(mesh);
    }

    // Try ASCII format
    file.seek(SeekFrom::Start(0))
        .map_err(|e| format!("Seek error: {}", e))?;
    parse_stl_ascii(&mut file)
}

fn parse_stl_binary(file: &mut File) -> Result<Mesh, String> {
    let mut header = [0u8; 80];
    file.read_exact(&mut header)
        .map_err(|e| format!("Failed to read header: {}", e))?;

    let mut num_triangles_bytes = [0u8; 4];
    file.read_exact(&mut num_triangles_bytes)
        .map_err(|e| format!("Failed to read triangle count: {}", e))?;

    let num_triangles = u32::from_le_bytes(num_triangles_bytes) as usize;

    let mut vertices = Vec::new();
    let mut faces = Vec::new();

    for _ in 0..num_triangles {
        let mut normal_bytes = [0u8; 12];
        file.read_exact(&mut normal_bytes)
            .map_err(|e| format!("Failed to read normal: {}", e))?;

        let mut v1_bytes = [0u8; 12];
        file.read_exact(&mut v1_bytes)
            .map_err(|e| format!("Failed to read vertex 1: {}", e))?;

        let mut v2_bytes = [0u8; 12];
        file.read_exact(&mut v2_bytes)
            .map_err(|e| format!("Failed to read vertex 2: {}", e))?;

