use crate::mesh::Mesh;
use crate::colors;
use crate::math::{Vec2, Vec3};
use std::f32;

const BACKGROUND_COLOR: (u8, u8, u8) = (25, 25, 25);

pub fn render_image(
    mesh: &Mesh,
    width: u32,
    height: u32,
    x_rot: f32,
    y_rot: f32,
    z_rot: f32,
    black_and_white: bool,
) {
    let mut mesh = mesh.clone();
    mesh.apply_rotation(x_rot, y_rot, z_rot);

    // Center and scale the mesh
    if let Some((min, max)) = mesh.get_bounds() {
        let center = Vec3::new(
            (min.x + max.x) / 2.0,
            (min.y + max.y) / 2.0,
            (min.z + max.z) / 2.0,
        );
        let size = Vec3::new(
            max.x - min.x,
            max.y - min.y,
            max.z - min.z,
        );
        let max_dim = size.x.max(size.y).max(size.z);

        // Scale to fit screen
        let scale = if max_dim > 0.0 {
            (width.min(height) as f32 * 0.8) / max_dim
        } else {
            1.0
        };

        for vertex in &mut mesh.vertices {
            vertex.position.x -= center.x;
            vertex.position.y -= center.y;
            vertex.position.z -= center.z;
            vertex.position.x *= scale;
            vertex.position.y *= scale;
            vertex.position.z *= scale;
        }
    }

    // Create framebuffer
    let mut framebuffer = vec![FramebufferPixel::default(); (width * height) as usize];
    let mut depthbuffer = vec![f32::MAX; (width * height) as usize];

    // Rasterize all faces
    for face in &mesh.faces {
        rasterize_triangle(
            &mesh,
            face.vertices,
            width,
            height,
            &mut framebuffer,
            &mut depthbuffer,
            black_and_white,
        );
    }

    // Output framebuffer
    output_framebuffer(&framebuffer, width, height);
}

#[derive(Clone, Copy, Default)]
struct FramebufferPixel {
    color: (u8, u8, u8),
}

