fn project_to_screen(pos: Vec3, width: u32, height: u32) -> Vec2 {
    let w = width as f32;
    let h = height as f32;

    // Simple orthographic projection centered
    let x = (pos.x + w / 2.0);
    let y = (pos.y + h / 2.0);

    Vec2::new(x, y)
}

fn barycentric(
    a: Vec2,
    b: Vec2,
    c: Vec2,
    p: Vec2,
) -> Option<(f32, f32, f32)> {
    let v0 = Vec2::new(c.x - a.x, c.y - a.y);
    let v1 = Vec2::new(b.x - a.x, b.y - a.y);
    let v2 = Vec2::new(p.x - a.x, p.y - a.y);

    let dot00 = v0.dot(&v0);
    let dot01 = v0.dot(&v1);
    let dot02 = v0.dot(&v2);
    let dot11 = v1.dot(&v1);
    let dot12 = v1.dot(&v2);

    let denom = dot00 * dot11 - dot01 * dot01;
    if denom.abs() < 1e-10 {
        return None;
    }

    let inv_denom = 1.0 / denom;
    let u = (dot11 * dot02 - dot01 * dot12) * inv_denom;
    let v = (dot00 * dot12 - dot01 * dot02) * inv_denom;
    let w = 1.0 - u - v;

    Some((u, v, w))
}

fn output_framebuffer(framebuffer: &[FramebufferPixel], width: u32, height: u32) {
    let mut output = String::new();

    for y in 0..height {
        for x in 0..width {
            let idx = (y * width + x) as usize;
            let color = framebuffer[idx].color;

            output.push_str(&colors::rgb_to_ansi_bg(color.0, color.1, color.2));
            output.push_str(&colors::rgb_to_ansi_fg(0, 0, 0));
            output.push(' ');
            output.push_str(colors::reset_bg());
            output.push_str(colors::reset_fg());
        }
        output.push('\n');
    }

    print!("{}", output);
}
