    if intensity < 0.1 {
        ' '
    } else if intensity < 0.25 {
        '.'
    } else if intensity < 0.4 {
        '-'
    } else if intensity < 0.55 {
        '*'
    } else if intensity < 0.7 {
        '+' 
    } else if intensity < 0.85 {
        '#'
    } else {
        '#'
    }
}
