pub struct Args {
    pub help: bool,
    pub version: bool,
    pub black_and_white: bool,
    pub x_rot: f32,
    pub y_rot: f32,
    pub z_rot: f32,
    pub input_files: Vec<String>,
    pub width: u32,
    pub height: u32,
    pub subcommand: String,
}

pub fn parse_args(args: Vec<String>) -> Args {
    let mut result = Args {
        help: false,
        version: false,
        black_and_white: false,
        x_rot: 0.0,
        y_rot: 0.0,
        z_rot: 0.0,
        input_files: Vec::new(),
        width: 800,
        height: 600,
        subcommand: String::new(),
    };

    let mut i = 1; // Skip program name
    let mut parsing_options = true;

    while i < args.len() {
        let arg = &args[i];

        if parsing_options && arg.starts_with('-') {
            match arg.as_str() {
                "-h" | "--help" => result.help = true,
                "-V" | "--version" => result.version = true,
                "-b" => result.black_and_white = true,
                "-x" | "--yaw" => {
                    i += 1;
                    if i < args.len() {
                        result.x_rot = args[i].parse().unwrap_or(0.0);
                    }
                }
                "-y" | "--pitch" => {
                    i += 1;
                    if i < args.len() {
                        result.y_rot = args[i].parse().unwrap_or(0.0);
                    }
                }
                "-z" | "--roll" => {
                    i += 1;
                    if i < args.len() {
                        result.z_rot = args[i].parse().unwrap_or(0.0);
                    }
                }
                "-w" | "--width" => {
                    i += 1;
                    if i < args.len() {
                        result.width = args[i].parse().unwrap_or(800);
                    }
                }
                "-height" => {
                    i += 1;
                    if i < args.len() {
                        result.height = args[i].parse().unwrap_or(600);
                    }
                }
                "-j" | "--webify" => {
                    i += 1;
                    // Skip the webify count for now
                }
                _ => {
                    parsing_options = false;
                    result.input_files.push(arg.clone());
                }
            }
        } else {
            // Check if this is a subcommand
            if (arg == "image" || arg == "help") && result.input_files.is_empty() {
                result.subcommand = arg.clone();
                i += 1;

                // Parse subcommand-specific arguments
                while i < args.len() {
                    let sub_arg = &args[i];
                    if sub_arg.starts_with('-') {
                        match sub_arg.as_str() {
                            "-b" => result.black_and_white = true,
                            "-w" | "--width" => {
                                i += 1;
                                if i < args.len() {
                                    result.width = args[i].parse().unwrap_or(800);
                                }
                            }
                            "-height" => {
                                i += 1;
                                if i < args.len() {
                                    result.height = args[i].parse().unwrap_or(600);
                                }
                            }
                            "-x" | "--yaw" => {
                                i += 1;
                                if i < args.len() {
                                    result.x_rot = args[i].parse().unwrap_or(0.0);
                                }
                            }
                            "-y" | "--pitch" => {
                                i += 1;
                                if i < args.len() {
                                    result.y_rot = args[i].parse().unwrap_or(0.0);
                                }
                            }
                            "-z" | "--roll" => {
                                i += 1;
                                if i < args.len() {
                                    result.z_rot = args[i].parse().unwrap_or(0.0);
                                }
                            }
                            "-j" | "--webify" => {
                                i += 1;
                                // Skip webify for now
                            }
                            _ => {}
                        }
                    } else {
                        // This shouldn't happen in the image subcommand
                    }
                    i += 1;
                }
                return result;
            } else {
                result.input_files.push(arg.clone());
            }
        }

        i += 1;
    }

    // If no subcommand was specified but we have files, use default rendering
    if result.subcommand.is_empty() && !result.input_files.is_empty() {
        result.subcommand = "render".to_string();
    }

    result
}
