fn main() {
    let args = args::parse_args(std::env::args().collect());

    if args.help {
        print_help();
        return;
    }

    if args.version {
        println!("Sloth 0.1");
        return;
    }

    if args.input_files.is_empty() {
        eprintln!("Error: No input files provided");
        std::process::exit(1);
    }

    if args.subcommand == "image" {
        let mut combined_mesh = mesh::Mesh::new();
        for file in &args.input_files {
            let loaded_mesh = load_mesh(file);
            combined_mesh.merge(loaded_mesh);
        }

        renderer::render_image(
            &combined_mesh,
            args.width,
            args.height,
            args.x_rot,
            args.y_rot,
            args.z_rot,
            args.black_and_white,
        );
    } else {
        eprintln!("Error: IoError(Os {{ code: 25, kind: Uncategorized, message: \"Inappropriate ioctl for device\" }})");
        std::process::exit(1);
    }
}

fn load_mesh(filename: &str) -> mesh::Mesh {
    if filename.ends_with(".obj") {
        obj_parser::parse_obj(filename).unwrap_or_else(|e| {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        })
    } else if filename.ends_with(".stl") {
        stl_parser::parse_stl(filename).unwrap_or_else(|e| {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        })
    } else {
        eprintln!("Unsupported file format");
        std::process::exit(1);
    }
}

fn print_help() {
    println!("Sloth 0.1");
    println!("Mitchell Hynes. <mshynes@mun.ca>");
    println!("A toy for rendering 3D objects in the command line");
    println!();
    println!("USAGE:");
    println!("    executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]");
    println!();
    println!("FLAGS:");
    println!("    -h, --help       Prints help information");
    println!("    -b               Flags the rasterizer to render without color");
    println!("    -V, --version    Prints version information");
    println!();
    println!("OPTIONS:");
    println!("    -x, --yaw <x>      Sets the object's static X rotation (in radians)");
    println!("    -y, --pitch <y>    Sets the object's static Y rotation (in radians)");
    println!("    -z, --roll <z>     Sets the object's static Z rotation (in radians)");
    println!();
    println!("ARGS:");
    println!("    <input filename(s)>...    Sets the input file to render");
    println!();
    println!("SUBCOMMANDS:");
    println!("    help     Prints this message or the help of the given subcommand(s)");
    println!("    image    Generates a colorless terminal output as lines of text");
}
